using System.Text.RegularExpressions;
using g0v0.LocalisationChecker.Model;

namespace g0v0.LocalisationChecker.Parsing;

/// <summary>
/// Parses a <c>*Strings.cs</c> localisation class.
/// </summary>
/// <remarks>
/// <para>
/// The files are machine-generated by <c>ppy.LocalisationAnalyser</c> in a rigid shape, so a lexer
/// plus structural regexes is both sufficient and far cheaper than pulling in Roslyn. The lexer
/// (<see cref="CSharpLexer"/>) removes string and comment bodies first, which is what makes the
/// regexes safe: without it, a translation containing <c>)</c>, <c>,</c> or <c>=&gt;</c> would
/// corrupt every match that follows it.
/// </para>
/// <para>
/// Note that the <c>key</c> argument of <c>getKey(@"...")</c> is an opaque literal - it is not
/// derived from the member name - so the literal is the only thing we can read.
/// </para>
/// </remarks>
internal static class StringsFileParser
{
    private static readonly Regex PrefixRegex =
        new(@"const\s+string\s+prefix\s*=\s*", RegexOptions.Compiled);

    private static readonly Regex ClassRegex =
        new(@"\b(?:class|struct|record)\s+([A-Za-z_][A-Za-z0-9_]*)", RegexOptions.Compiled);

    private static readonly Regex MemberRegex =
        new(@"public\s+static\s+LocalisableString\s+([A-Za-z_][A-Za-z0-9_]*)\s*(?:\(([^)]*)\))?\s*=>",
            RegexOptions.Compiled);

    private static readonly Regex TranslatableRegex =
        new(@"new\s+TranslatableString\s*\(", RegexOptions.Compiled);

    private static readonly Regex PluralisableRegex =
        new(@"new\s+PluralisableString\s*\(", RegexOptions.Compiled);

    private static readonly Regex GetKeyRegex =
        new(@"getKey\s*\(\s*", RegexOptions.Compiled);

    /// <summary>Parses <paramref name="source"/>, or returns null when it is not a localisation class.</summary>
    public static LocalisationClass? Parse(
        string absolutePath,
        string displayPath,
        string relativeDirectory,
        string source)
    {
        var text = new SourceText(source);
        CSharpLexer.ScanResult scan = CSharpLexer.Scan(source);
        string masked = scan.Masked;

        Match prefixMatch = PrefixRegex.Match(masked);
        if (!prefixMatch.Success)
            return null;

        StringLiteral? prefixCandidate = scan.LiteralAt(masked, prefixMatch.Index + prefixMatch.Length);
        if (prefixCandidate is null || prefixCandidate.Value.Value.Length == 0)
            return null;

        StringLiteral prefix = prefixCandidate.Value;

        Match classMatch = ClassRegex.Match(masked);
        string className = classMatch.Success
            ? classMatch.Groups[1].Value
            : Path.GetFileNameWithoutExtension(absolutePath);

        var members = new List<LocalisationMember>();
        MatchCollection memberMatches = MemberRegex.Matches(masked);

        for (int index = 0; index < memberMatches.Count; index++)
        {
            Match match = memberMatches[index];
            int start = match.Index;
            int end = index + 1 < memberMatches.Count ? memberMatches[index + 1].Index : masked.Length;

            string name = match.Groups[1].Value;
            bool hasParameters = match.Groups[2].Success && match.Groups[2].Value.Trim().Length > 0;
            int line = text.LineOf(start);

            Match translatable = TranslatableRegex.Match(masked, start);
            Match plural = PluralisableRegex.Match(masked, start);

            bool hasTranslatable = translatable.Success && translatable.Index < end;
            bool hasPlural = plural.Success && plural.Index < end;
            bool isPlural = hasPlural && (!hasTranslatable || plural.Index < translatable.Index);

            StringLiteral? keyLiteral = null;
            StringLiteral? fallbackLiteral = null;

            if (hasTranslatable)
            {
                // The first argument is always getKey(@"..."), so the key literal is the one that
                // follows the getKey call - not the one that follows the constructor.
                Match getKey = GetKeyRegex.Match(masked, translatable.Index + translatable.Length);

                if (getKey.Success && getKey.Index < end)
                {
                    keyLiteral = scan.LiteralAt(masked, getKey.Index + getKey.Length);

                    // The fallback is whatever literal comes next inside the same member.
                    if (keyLiteral is not null)
                        fallbackLiteral = scan.NextLiteral(keyLiteral.Value.End, end);
                }
            }

            MemberKind kind = isPlural
                ? MemberKind.Plural
                : hasParameters
                    ? MemberKind.Method
                    : MemberKind.Property;

            members.Add(new LocalisationMember
            {
                Name = name,
                Kind = kind,
                Line = line,
                Key = keyLiteral?.Value,
                Fallback = fallbackLiteral?.Value,
                Documentation = XmldocText.Extract(CollectDocLines(text.Lines, line)),
            });
        }

        return new LocalisationClass
        {
            AbsolutePath = absolutePath,
            DisplayPath = displayPath,
            ClassName = className,
            Prefix = prefix.Value,
            PrefixLine = text.LineOf(prefix.Start),
            RelativeDirectory = relativeDirectory,
            Members = members,
        };
    }

    /// <summary>Walks upwards from a member collecting the contiguous <c>///</c> block above it.</summary>
    private static IReadOnlyList<string> CollectDocLines(string[] lines, int memberLine)
    {
        var collected = new List<string>();
        int index = memberLine - 2;

        while (index >= 0)
        {
            if (!lines[index].TrimStart().StartsWith("///", StringComparison.Ordinal))
                break;

            collected.Insert(0, lines[index]);
            index--;
        }

        return collected;
    }
}
